typedef struct { char *d; size_t len, cap; } buf_t;

struct pdf {
  buf_t *pages;
  size_t n_pages, cap_pages;
  int err;
};

static int buf_put(buf_t *b, const char *s, size_t n) {
  if (b->len + n + 1 > b->cap) {
    size_t nc = b->cap ? b->cap : 256;
    while (nc < b->len + n + 1) nc *= 2;
    char *nd = realloc(b->d, nc);
    if (!nd) return -1;
    b->d = nd; b->cap = nc;
  }
  memcpy(b->d + b->len, s, n);
  b->len += n;
  b->d[b->len] = 0;
  return 0;
}

static int buf_printf(buf_t *b, const char *fmt, ...) __attribute__((format(printf, 2, 3)));
static int buf_printf(buf_t *b, const char *fmt, ...) {
  char tmp[256];
  va_list ap;
  va_start(ap, fmt);
  int n = vsnprintf(tmp, sizeof tmp, fmt, ap);
  va_end(ap);
  if (n < 0 || (size_t)n >= sizeof tmp) return -1;
  return buf_put(b, tmp, (size_t)n);
}

#define PUTS(b, lit) buf_put((b), (lit), sizeof(lit) - 1)

pdf_t *pdf_new(void) { return calloc(1, sizeof(pdf_t)); }

void pdf_page(pdf_t *p) {
  if (p->err) return;
  if (p->n_pages == p->cap_pages) {
    size_t nc = p->cap_pages ? p->cap_pages * 2 : 4;
    buf_t *np = realloc(p->pages, nc * sizeof *np);
    if (!np) { p->err = 1; return; }
    p->pages = np; p->cap_pages = nc;
  }
  memset(&p->pages[p->n_pages++], 0, sizeof(buf_t));
}

/* Next UTF-8 sequence as a WinAnsi code (never 0); advances *sp. */
static unsigned char next_winansi(const char **sp) {
  const unsigned char *s = (const unsigned char *)*sp;
  unsigned cp = '?';
  int n = 1;
  if (s[0] < 0x80) cp = s[0];
  else if ((s[0] & 0xE0) == 0xC0 && (s[1] & 0xC0) == 0x80) { cp = (s[0] & 0x1Fu) << 6 | (s[1] & 0x3Fu); n = 2; }
  else if ((s[0] & 0xF0) == 0xE0 && (s[1] & 0xC0) == 0x80 && (s[2] & 0xC0) == 0x80) {
    cp = (s[0] & 0x0Fu) << 12 | (s[1] & 0x3Fu) << 6 | (s[2] & 0x3Fu); n = 3;
  } else if ((s[0] & 0xF8) == 0xF0 && (s[1] & 0xC0) == 0x80 && (s[2] & 0xC0) == 0x80 && (s[3] & 0xC0) == 0x80) {
    cp = 0x10000; n = 4;   /* outside every mapping below */
  }
  *sp += n;
  if (cp >= 0x20 && cp <= 0x7E) return (unsigned char)cp;
  if (cp >= 0xA0 && cp <= 0xFF) return (unsigned char)cp;
  switch (cp) {
    case 0x20AC: return 0x80;
    case 0x201E: return 0x84;
    case 0x201C: return 0x93;
    case 0x2013: return 0x96;
    default: return '?';
  }
}

int pdf_winansi(const char *utf8, char *out, size_t cap) {
  size_t n = 0;
  while (*utf8) {
    unsigned char c = next_winansi(&utf8);
    if (n + 1 >= cap) return -1;
    out[n++] = (char)c;
  }
  if (cap == 0) return -1;
  out[n] = 0;
  return (int)n;
}

int pdf_text_width(int font, int size, const char *utf8) {
  const unsigned short *w = font == 1 ? helvb_w : helv_w;
  long sum = 0;
  while (*utf8) {
    unsigned char c = next_winansi(&utf8);
    sum += w[c - 32];
  }
  return (int)((sum * size + 999) / 1000);
}

static buf_t *cur(pdf_t *p) {
  if (p->err) return NULL;
  if (p->n_pages == 0) { p->err = 1; return NULL; }
  return &p->pages[p->n_pages - 1];
}

void pdf_text(pdf_t *p, int font, int size, int x, int y, const char *utf8) {
  buf_t *b = cur(p);
  if (!b) return;
  char wa[512];
  if ((font != 0 && font != 1) || size <= 0 || pdf_winansi(utf8, wa, sizeof wa) < 0) { p->err = 1; return; }
  int rc = buf_printf(b, "BT /F%d %d Tf %d %d Td (", font + 1, size, x, y);
  for (const unsigned char *s = (const unsigned char *)wa; rc == 0 && *s; s++) {
    char e[8];
    int n;
    if (*s == '(' || *s == ')' || *s == '\\') n = snprintf(e, sizeof e, "\\%c", *s);
    else if (*s >= 0x80 || *s < 0x20) n = snprintf(e, sizeof e, "\\%03o", *s);
    else { e[0] = (char)*s; n = 1; }
    rc = buf_put(b, e, (size_t)n);
  }
  if (rc == 0) rc = PUTS(b, ") Tj ET\n");
  if (rc) p->err = 1;
}

void pdf_text_right(pdf_t *p, int font, int size, int x_right, int y, const char *utf8) {
  pdf_text(p, font, size, x_right - pdf_text_width(font, size, utf8), y, utf8);
}

void pdf_hline(pdf_t *p, int x1, int x2, int y) {
  buf_t *b = cur(p);
  if (b && buf_printf(b, "0.5 w %d %d m %d %d l S\n", x1, y, x2, y)) p->err = 1;
}

static void free_pdf(pdf_t *p) {
  for (size_t i = 0; i < p->n_pages; i++) free(p->pages[i].d);
  free(p->pages);
  free(p);
}

int pdf_finish(pdf_t *p, char **out, size_t *len) {
  buf_t f = {0};
  size_t *off = NULL;
  int rc = -1;
  if (p->err || p->n_pages == 0) goto done;
  size_t n_obj = 4 + 2 * p->n_pages;          /* 1 catalog, 2 pages, 3/4 fonts, then page + content */
  off = calloc(n_obj + 1, sizeof *off);
  if (!off) goto done;
  if (PUTS(&f, "%PDF-1.4\n%\xE2\xE3\xCF\xD3\n")) goto done;
#define OBJ(n) (off[n] = f.len, buf_printf(&f, "%zu 0 obj\n", (size_t)(n)))
  if (OBJ(1) || PUTS(&f, "<< /Type /Catalog /Pages 2 0 R >>\nendobj\n")) goto done;
  if (OBJ(2) || PUTS(&f, "<< /Type /Pages /Kids [")) goto done;
  for (size_t i = 0; i < p->n_pages; i++)
    if (buf_printf(&f, "%zu 0 R ", 5 + 2 * i)) goto done;
  if (buf_printf(&f, "] /Count %zu >>\nendobj\n", p->n_pages)) goto done;
  if (OBJ(3) || buf_printf(&f, "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>\nendobj\n")) goto done;
  if (OBJ(4) || buf_printf(&f, "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>\nendobj\n")) goto done;
  for (size_t i = 0; i < p->n_pages; i++) {
    size_t pg = 5 + 2 * i, ct = pg + 1;
    if (OBJ(pg) || buf_printf(&f, "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] "
                                  "/Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents %zu 0 R >>\nendobj\n", ct)) goto done;
    if (OBJ(ct) || buf_printf(&f, "<< /Length %zu >>\nstream\n", p->pages[i].len)) goto done;
    if ((p->pages[i].len && buf_put(&f, p->pages[i].d, p->pages[i].len)) || PUTS(&f, "endstream\nendobj\n")) goto done;
  }
#undef OBJ
  size_t xref = f.len;
  if (buf_printf(&f, "xref\n0 %zu\n0000000000 65535 f \n", n_obj + 1)) goto done;
  for (size_t i = 1; i <= n_obj; i++)
    if (buf_printf(&f, "%010zu 00000 n \n", off[i])) goto done;
  if (buf_printf(&f, "trailer\n<< /Size %zu /Root 1 0 R >>\nstartxref\n%zu\n%%%%EOF\n", n_obj + 1, xref)) goto done;
  *out = f.d; *len = f.len;
  f.d = NULL;
  rc = 0;
done:
  free(f.d);
  free(off);
  free_pdf(p);
  return rc;
}
